import { useState, useEffect } from "react";

const API = "http://localhost:3000/api";

/* ---- DDMS brand palette ---- */
const BRAND = {
  teal: "#0F3D3B",
  tealDeep: "#082221",
  tealMid: "#144B47",
  gold: "#E8992B",
  goldSoft: "#FCF0DC",
  blue: "#1F5C9E",
  blueSoft: "#E7F0FA",
  red: "#D5402F",
  redSoft: "#FBE7E3",
  cream: "#F4F7F5",
  muted: "#8B8578",
};

const STATUS_STYLES = {
  pending:  { bg: BRAND.goldSoft, color: "#96631B", label: "Pending",  dot: BRAND.gold },
  reviewed: { bg: BRAND.blueSoft, color: BRAND.blue, label: "Reviewed", dot: BRAND.blue },
  resolved: { bg: "#E3F0EC",      color: BRAND.teal, label: "Resolved", dot: BRAND.teal },
};

function Badge({ status }) {
  const s = STATUS_STYLES[status] || STATUS_STYLES.pending;
  return (
    <span style={{
      background: s.bg, color: s.color,
      padding: "3px 10px", borderRadius: 20,
      fontSize: 11, fontWeight: 700,
      textTransform: "uppercase", letterSpacing: ".5px",
      display: "inline-flex", alignItems: "center", gap: 5,
      whiteSpace: "nowrap",
    }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: s.dot, display: "inline-block" }} />
      {s.label}
    </span>
  );
}

function StarRating({ value, onChange }) {
  const [hover, setHover] = useState(0);
  return (
    <div style={{ display: "flex", gap: 8, justifyContent: "center", marginBottom: 20 }}>
      {[1, 2, 3, 4, 5].map(n => {
        const filled = n <= (hover || value);
        return (
          <button
            key={n}
            type="button"
            onClick={() => onChange(n)}
            onMouseEnter={() => setHover(n)}
            onMouseLeave={() => setHover(0)}
            aria-label={`${n} star${n > 1 ? "s" : ""}`}
            style={{ background: "none", border: "none", cursor: "pointer", padding: 2, lineHeight: 0 }}
          >
            <svg width="30" height="30" viewBox="0 0 24 24" fill={filled ? BRAND.gold : "none"} stroke={filled ? BRAND.gold : BRAND.muted} strokeWidth="1.6">
              <path d="M12 2.5l2.9 6.1 6.6.7-4.9 4.5 1.3 6.6L12 17l-5.9 3.4 1.3-6.6-4.9-4.5 6.6-.7z" strokeLinejoin="round" />
            </svg>
          </button>
        );
      })}
    </div>
  );
}

/* ── CITIZEN FEEDBACK PAGE ──────────────────────────────────── */
export function CitizenFeedbackPage({ token, user }) {
  const [rating, setRating]       = useState(0);
  const [details, setDetails]     = useState("");
  const [loading, setLoading]     = useState(false);
  const [success, setSuccess]     = useState("");
  const [error, setError]         = useState("");
  const [myFeedback, setMyFeedback] = useState([]);
  const [fetching, setFetching]   = useState(true);

  function loadMyFeedback() {
    setFetching(true);
    fetch(`${API}/feedback/mine`, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { if (d.success) setMyFeedback(d.data); })
      .finally(() => setFetching(false));
  }

  useEffect(() => { loadMyFeedback(); }, []);

  async function handleSubmit(e) {
    e.preventDefault();
    if (!details.trim()) return;
    setLoading(true); setError(""); setSuccess("");
    try {
      const res = await fetch(`${API}/feedback`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ details, rating: rating || undefined }),
      });
      const data = await res.json();
      if (data.success) {
        setSuccess("Feedback submitted successfully. We will review it shortly.");
        setDetails(""); setRating(0);
        loadMyFeedback();
      } else {
        setError(data.message || "Submission failed");
      }
    } catch { setError("Could not reach the server."); }
    finally { setLoading(false); }
  }

  return (
    <div style={{
      background: `linear-gradient(160deg, ${BRAND.tealDeep} 0%, ${BRAND.teal} 55%, ${BRAND.tealMid} 100%)`,
      minHeight: "100vh",
      padding: "48px 20px",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
    }}>

      {/* Feedback card */}
      <div style={{
        position: "relative",
        background: "#fff",
        borderRadius: 24,
        padding: "40px 36px 32px",
        width: "100%",
        maxWidth: 460,
        boxShadow: "0 30px 70px -30px rgba(0,0,0,0.45)",
      }}>
        <h1 style={{
          margin: "0 0 12px", fontSize: 24, fontWeight: 800,
          color: BRAND.teal, textAlign: "center", lineHeight: 1.3,
        }}>
          We appreciate your feedback.
        </h1>
        <p style={{
          margin: "0 0 26px", fontSize: 13.5, color: BRAND.muted,
          textAlign: "center", lineHeight: 1.65,
        }}>
          Share your thoughts, concerns, or suggestions about district projects and services.
        </p>

        <StarRating value={rating} onChange={setRating} />

        <form onSubmit={handleSubmit}>
          <textarea
            value={details}
            onChange={e => setDetails(e.target.value)}
            placeholder="What can we do to improve your experience?"
            required
            rows={5}
            style={{
              width: "100%", padding: "14px 16px", boxSizing: "border-box",
              border: "1px solid #E3E8E5", borderRadius: 12,
              fontSize: 14, color: BRAND.teal, background: "#FAFCFB",
              resize: "vertical", outline: "none", lineHeight: 1.7,
              fontFamily: "inherit", marginBottom: 14,
            }}
            onFocus={e => e.target.style.border = `1px solid ${BRAND.teal}`}
            onBlur={e => e.target.style.border = "1px solid #E3E8E5"}
          />

          {success && (
            <div style={{
              margin: "0 0 14px", padding: "12px 16px",
              background: "#E3F0EC", border: "1px solid #B9DAD2",
              borderRadius: 10, fontSize: 13, color: BRAND.teal,
            }}>
              ✓ {success}
            </div>
          )}
          {error && (
            <div style={{
              margin: "0 0 14px", padding: "12px 16px",
              background: BRAND.redSoft, border: "1px solid #F3B8AE",
              borderRadius: 10, fontSize: 13, color: "#A62E20",
            }}>
              {error}
            </div>
          )}

          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 16 }}>
            <p style={{ margin: 0, fontSize: 11.5, color: BRAND.muted }}>{details.length} characters</p>
          </div>

          <button
            type="submit"
            disabled={loading || !details.trim()}
            style={{
              width: "100%", padding: "14px",
              background: loading || !details.trim() ? "#BFD9D3" : BRAND.teal,
              color: "#fff", border: "none", borderRadius: 12,
              fontSize: 15, fontWeight: 700,
              cursor: loading || !details.trim() ? "not-allowed" : "pointer",
              transition: "background .15s",
            }}
          >
            {loading ? "Submitting..." : "Submit My Feedback"}
          </button>
        </form>
      </div>

      {/* brand footer, echoing the reference's logo row */}
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 22 }}>
        <img
          src="data:image/png;base64,"
          alt="DDMS seal"
          style={{ width: 30, height: 30, borderRadius: "50%" }}
        />
        <span style={{ fontSize: 15, fontWeight: 800, color: "#F4EFE0" }}>DDMS 2026</span>
      </div>

      {/* My feedback history */}
      <div style={{
        width: "100%", maxWidth: 460, marginTop: 32,
        background: "#fff", border: "1px solid #E9E2D2", borderRadius: 16,
        padding: "22px 24px",
      }}>
        <h3 style={{ margin: "0 0 16px", fontSize: 13, fontWeight: 700, color: BRAND.teal, textTransform: "uppercase", letterSpacing: ".05em" }}>
          My Submissions
        </h3>
        {fetching ? (
          <p style={{ color: BRAND.muted, fontSize: 13, textAlign: "center", padding: "20px 0" }}>Loading...</p>
        ) : myFeedback.length === 0 ? (
          <p style={{ color: BRAND.muted, fontSize: 13, textAlign: "center", padding: "20px 0" }}>
            No feedback submitted yet.
          </p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {myFeedback.map(f => (
              <div key={f.feedback_id} style={{
                padding: "14px 16px",
                background: BRAND.cream,
                border: "1px solid #EEF1EF",
                borderRadius: 10,
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12, marginBottom: 8 }}>
                  <p style={{ margin: 0, fontSize: 13, color: BRAND.teal, lineHeight: 1.6, flex: 1 }}>
                    {f.details}
                  </p>
                  <Badge status={f.status} />
                </div>
                <p style={{ margin: 0, fontSize: 11, color: BRAND.muted }}>
                  Submitted {new Date(f.creation_date).toLocaleDateString("en-NP", { year: "numeric", month: "short", day: "numeric" })}
                </p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* ── ADMIN FEEDBACK PAGE ──────────────────────────────────────── */
export function AdminFeedbackPage({ token }) {
  const [all, setAll]           = useState([]);
  const [selected, setSelected] = useState(null);
  const [history, setHistory]   = useState([]);
  const [filter, setFilter]     = useState("all");
  const [loading, setLoading]   = useState(true);
  const [updating, setUpdating] = useState(false);
  const [newStatus, setNewStatus] = useState("");
  const [note, setNote]         = useState("");
  const [msg, setMsg]           = useState("");

  function loadAll() {
    setLoading(true);
    fetch(`${API}/feedback`, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { if (d.success) setAll(d.data); })
      .finally(() => setLoading(false));
  }

  useEffect(() => { loadAll(); }, []);

  async function openDetail(f) {
    setSelected(f);
    setNewStatus(f.status);
    setNote(""); setMsg("");
    const res = await fetch(`${API}/feedback/${f.feedback_id}`, { headers: { Authorization: `Bearer ${token}` } });
    const data = await res.json();
    if (data.success) setHistory(data.data.history || []);
  }

  async function handleUpdate() {
    setUpdating(true); setMsg("");
    try {
      const res = await fetch(`${API}/feedback/${selected.feedback_id}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ status: newStatus, change_note: note || null }),
      });
      const data = await res.json();
      if (data.success) {
        setMsg("Status updated successfully.");
        loadAll();
        const res2 = await fetch(`${API}/feedback/${selected.feedback_id}`, { headers: { Authorization: `Bearer ${token}` } });
        const d2   = await res2.json();
        if (d2.success) {
          setSelected(prev => ({ ...prev, status: newStatus }));
          setHistory(d2.data.history || []);
        }
      } else {
        setMsg(data.message || "Update failed");
      }
    } catch { setMsg("Could not reach the server."); }
    finally { setUpdating(false); }
  }

  const counts = {
    all:      all.length,
    pending:  all.filter(f => f.status === "pending").length,
    reviewed: all.filter(f => f.status === "reviewed").length,
    resolved: all.filter(f => f.status === "resolved").length,
  };
  const filtered = filter === "all" ? all : all.filter(f => f.status === filter);

  const STAT_TILES = [
    { key: "all",      label: "Total",    color: BRAND.teal, bg: BRAND.cream },
    { key: "pending",  label: "Pending",  color: "#96631B",  bg: BRAND.goldSoft },
    { key: "reviewed", label: "Reviewed", color: BRAND.blue, bg: BRAND.blueSoft },
    { key: "resolved", label: "Resolved", color: BRAND.teal, bg: "#E3F0EC" },
  ];

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "28px 24px" }}>
      <div style={{ marginBottom: 24 }}>
        <h1 style={{ margin: "0 0 4px", fontSize: 22, fontWeight: 700, color: BRAND.teal }}>
          Feedback Management
        </h1>
        <p style={{ margin: 0, color: BRAND.muted, fontSize: 13 }}>
          Review and respond to citizen feedback
        </p>
      </div>

      {/* Stats */}
      <div style={{ display: "flex", gap: 10, marginBottom: 24, flexWrap: "wrap" }}>
        {STAT_TILES.map(s => (
          <div
            key={s.key}
            onClick={() => setFilter(s.key)}
            style={{
              background: filter === s.key ? s.color : s.bg,
              color: filter === s.key ? "#fff" : s.color,
              borderRadius: 10, padding: "12px 20px",
              cursor: "pointer", flex: 1, minWidth: 100,
              border: `2px solid ${s.color}`,
              textAlign: "center", transition: "all 0.15s",
            }}
          >
            <div style={{ fontSize: 22, fontWeight: 800 }}>{counts[s.key]}</div>
            <div style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".5px" }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
        {/* Left — feedback list */}
        <div style={{ flex: 1, minWidth: 0 }}>
          {loading ? (
            <p style={{ color: BRAND.muted, textAlign: "center", padding: 40 }}>Loading...</p>
          ) : filtered.length === 0 ? (
            <div style={{ background: "#fff", border: "1px solid #E9E2D2", borderRadius: 12, padding: 40, textAlign: "center" }}>
              <p style={{ color: BRAND.muted, margin: 0 }}>No {filter === "all" ? "" : filter} feedback yet.</p>
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {filtered.map(f => (
                <div
                  key={f.feedback_id}
                  onClick={() => openDetail(f)}
                  style={{
                    background: "#fff",
                    border: selected?.feedback_id === f.feedback_id ? `2px solid ${BRAND.teal}` : "1px solid #E9E2D2",
                    borderRadius: 10, padding: "14px 18px",
                    cursor: "pointer", transition: "all 0.15s",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10, marginBottom: 8 }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ margin: "0 0 4px", fontSize: 12, fontWeight: 700, color: BRAND.muted, textTransform: "uppercase", letterSpacing: ".5px" }}>
                        {f.submitted_by_name || "Anonymous"} · #{f.feedback_id}
                      </p>
                      <p style={{ margin: 0, fontSize: 13, color: BRAND.teal, lineHeight: 1.5 }}>
                        {f.details.length > 120 ? f.details.slice(0, 120) + "…" : f.details}
                      </p>
                    </div>
                    <Badge status={f.status} />
                  </div>
                  <p style={{ margin: 0, fontSize: 11, color: BRAND.muted }}>
                    {new Date(f.creation_date).toLocaleDateString("en-NP", { year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Right — detail panel */}
        {selected && (
          <div style={{
            width: 340, flexShrink: 0,
            background: "#fff", border: "1px solid #E9E2D2",
            borderRadius: 12, padding: "20px 22px",
            position: "sticky", top: 70,
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <h3 style={{ margin: 0, fontSize: 14, fontWeight: 700, color: BRAND.teal }}>
                Feedback #{selected.feedback_id}
              </h3>
              <button
                onClick={() => setSelected(null)}
                style={{ background: "none", border: "none", cursor: "pointer", color: BRAND.muted, fontSize: 18 }}
              >×</button>
            </div>
            <div style={{ marginBottom: 14, padding: "12px 14px", background: BRAND.cream, borderRadius: 8 }}>
              <p style={{ margin: "0 0 6px", fontSize: 11, color: BRAND.muted, textTransform: "uppercase", letterSpacing: ".5px" }}>From</p>
              <p style={{ margin: 0, fontSize: 13, fontWeight: 600, color: BRAND.teal }}>{selected.submitted_by_name || "Anonymous"}</p>
              <p style={{ margin: "2px 0 0", fontSize: 11, color: BRAND.muted }}>
                {new Date(selected.creation_date).toLocaleDateString()}
              </p>
            </div>
            <div style={{ marginBottom: 16, padding: "12px 14px", background: BRAND.cream, borderRadius: 8 }}>
              <p style={{ margin: "0 0 6px", fontSize: 11, color: BRAND.muted, textTransform: "uppercase", letterSpacing: ".5px" }}>Message</p>
              <p style={{ margin: 0, fontSize: 13, color: BRAND.teal, lineHeight: 1.7 }}>{selected.details}</p>
            </div>

            {/* Update status */}
            <div style={{ marginBottom: 16 }}>
              <p style={{ margin: "0 0 8px", fontSize: 11, color: BRAND.muted, textTransform: "uppercase", letterSpacing: ".5px" }}>Update Status</p>
              <select
                value={newStatus}
                onChange={e => setNewStatus(e.target.value)}
                style={{
                  width: "100%", padding: "9px 12px", boxSizing: "border-box",
                  border: "1px solid #D8DEDA", borderRadius: 8,
                  fontSize: 13, color: BRAND.teal, background: "#FAFCFB", marginBottom: 8,
                }}
              >
                <option value="pending">Pending</option>
                <option value="reviewed">Reviewed</option>
                <option value="resolved">Resolved</option>
              </select>
              <textarea
                value={note}
                onChange={e => setNote(e.target.value)}
                placeholder="Add a note (optional)..."
                rows={3}
                style={{
                  width: "100%", padding: "9px 12px", boxSizing: "border-box",
                  border: "1px solid #D8DEDA", borderRadius: 8,
                  fontSize: 13, color: BRAND.teal, background: "#FAFCFB",
                  resize: "none", outline: "none", fontFamily: "inherit",
                }}
              />
              {msg && (
                <p style={{ margin: "8px 0 0", fontSize: 12, color: msg.includes("success") ? BRAND.teal : "#A62E20" }}>
                  {msg}
                </p>
              )}
              <button
                onClick={handleUpdate}
                disabled={updating || newStatus === selected.status}
                style={{
                  width: "100%", marginTop: 10, padding: "10px",
                  background: updating || newStatus === selected.status ? "#BFD9D3" : BRAND.teal,
                  color: "#fff", border: "none", borderRadius: 8,
                  fontSize: 13, fontWeight: 600,
                  cursor: updating || newStatus === selected.status ? "not-allowed" : "pointer",
                }}
              >
                {updating ? "Updating..." : "Update Status"}
              </button>
            </div>

            {/* History */}
            {history.length > 0 && (
              <div>
                <p style={{ margin: "0 0 10px", fontSize: 11, color: BRAND.muted, textTransform: "uppercase", letterSpacing: ".5px" }}>
                  History
                </p>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {history.map(h => (
                    <div key={h.id} style={{
                      padding: "10px 12px", background: BRAND.cream,
                      borderRadius: 8, borderLeft: `3px solid ${BRAND.gold}`,
                    }}>
                      <div style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 4 }}>
                        <Badge status={h.old_status} />
                        <span style={{ fontSize: 11, color: BRAND.muted }}>→</span>
                        <Badge status={h.new_status} />
                      </div>
                      {h.change_note && <p style={{ margin: "4px 0 0", fontSize: 12, color: BRAND.teal }}>{h.change_note}</p>}
                      <p style={{ margin: "4px 0 0", fontSize: 11, color: BRAND.muted }}>
                        {h.changed_by_name} · {new Date(h.date).toLocaleDateString()}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
